import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"WAF — enumerated source for the Azure Machine Learning technology review","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-machine-learning-checklist.md","filePath":"frameworks/waf-machine-learning-checklist.md"}'),o={name:"frameworks/waf-machine-learning-checklist.md"};function n(i,t,s,c,l,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="waf-—-enumerated-source-for-the-azure-machine-learning-technology-review" tabindex="-1">WAF — enumerated source for the Azure Machine Learning technology review <a class="header-anchor" href="#waf-—-enumerated-source-for-the-azure-machine-learning-technology-review" aria-label="Permalink to &quot;WAF — enumerated source for the Azure Machine Learning technology review&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>waf.machinelearning.yaml</code> scores the Azure Machine Learning review. This page enumerates the Azure Well-Architected Framework Azure Machine Learning service guide, item by item, and the rule file is written against this page only; every rule cites an item number from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/eec33ce4-4ef0-4bd2-9f69-1956e50465d4/" target="_blank" rel="noreferrer">Azure Machine Learning — Well-Architected Review</a> (question text not published)</td></tr><tr><td>Framework version</td><td>Azure Well-Architected Framework Azure Machine Learning service guide, current at extraction</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The service guide was fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25; every design-checklist bullet and configuration-recommendation row was read. The ARM properties the automated items read were checked against the collection queries in <code>src/collect/Invoke-Collect.ps1</code>; the workspace property names were not re-verified against the ARM template reference in this pass.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list.</strong> The assessment&#39;s questions are not published. The items below are <strong>Scout&#39;s</strong> reading of the service guide and the <code>WAF-ML-*</code> ids are Scout&#39;s. The guide&#39;s technology scope is Machine Learning, compute clusters and compute instances; it does not address connected resources such as data stores or Key Vault, so those are only evidence here.</p><p>Sources (the code after each item names the page and section; -C is a workload design checklist bullet, -R a configuration recommendations row):</p><ul><li>[MLG] <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-machine-learning" target="_blank" rel="noreferrer">Architecture best practices for Azure Machine Learning</a>, sections Reliability, Security, Cost Optimization, Operational Excellence, Performance Efficiency</li></ul><p>The workspace dataset also carries <code>hbiWorkspace</code> (high business impact) and <code>v1LegacyMode</code>; neither answers an item in the guide, so they are evidence only. Items about compute clusters, compute instances, online endpoints and registries are manual: those are child resources of the workspace that the assessment collection does not read. The report that accompanies this page lists the projections that would automate them.</p><h2 id="the-enumeration-—-44-items" tabindex="-1">The enumeration — 44 items <a class="header-anchor" href="#the-enumeration-—-44-items" aria-label="Permalink to &quot;The enumeration — 44 items&quot;">​</a></h2><h3 id="reliability-waf-ml-re-—-9-items" tabindex="-1">Reliability (WAF-ML-RE) — 9 items <a class="header-anchor" href="#reliability-waf-ml-re-—-9-items" aria-label="Permalink to &quot;Reliability (WAF-ML-RE) — 9 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ML-RE-01</td><td>Models are deployed to environments that support availability zones</td><td>❌ Manual — the hosts models run on (AKS, managed online endpoints) are not collected; workspaces attached</td><td>MLG-RE-C</td></tr><tr><td>WAF-ML-RE-02</td><td>Compute for training and inferencing is sized to the workload</td><td>❌ Manual — capacity-planning judgement</td><td>MLG-RE-C</td></tr><tr><td>WAF-ML-RE-03</td><td>Exploratory workspaces are separate from production workspaces</td><td>❌ Manual — workspace purpose is not an ARM property; workspaces attached</td><td>MLG-RE-C</td></tr><tr><td>WAF-ML-RE-04</td><td>Managed online endpoints use a blue-green or traffic-split release</td><td>❌ Manual — endpoint deployments are child resources, not collected</td><td>MLG-RE-C</td></tr><tr><td>WAF-ML-RE-05</td><td>Compute type (clusters, instances, external inference hosts) is chosen from reliability needs and SLAs</td><td>❌ Manual — architecture judgement</td><td>MLG-RE-C</td></tr><tr><td>WAF-ML-RE-06</td><td>Long training runs checkpoint so they can resume after interruption</td><td>❌ Manual — training code, not ARM</td><td>MLG-RE-C, MLG-RE-R</td></tr><tr><td>WAF-ML-RE-07</td><td>A recovery strategy covers the workspace and its dependencies (Key Vault, Storage, Container Registry)</td><td>❌ Manual — recovery plans are not collected; workspaces attached</td><td>MLG-RE-C</td></tr><tr><td>WAF-ML-RE-08</td><td>A multi-region deployment is considered for models that must survive a regional outage</td><td>❌ Manual — workspaces attached with their region</td><td>MLG-RE-R</td></tr><tr><td>WAF-ML-RE-09</td><td>Compute clusters used for batch inferencing use the Dedicated VM tier</td><td>❌ Manual — compute clusters are child resources, not collected</td><td>MLG-RE-R</td></tr></tbody></table><h3 id="security-waf-ml-se-—-15-items" tabindex="-1">Security (WAF-ML-SE) — 15 items <a class="header-anchor" href="#security-waf-ml-se-—-15-items" aria-label="Permalink to &quot;Security (WAF-ML-SE) — 15 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ML-SE-01</td><td>The Azure security baseline for Machine Learning is applied and monitored</td><td>❌ Manual — baseline compliance is not an ARM property</td><td>MLG-SE-R</td></tr><tr><td>WAF-ML-SE-02</td><td>Workspaces use managed virtual network isolation</td><td>✅ workspace managed-network isolation mode</td><td>MLG-SE-C, MLG-SE-R</td></tr><tr><td>WAF-ML-SE-03</td><td>Workspace public network access is disabled</td><td>✅ workspace publicNetworkAccess</td><td>MLG-SE-C, MLG-SE-R</td></tr><tr><td>WAF-ML-SE-04</td><td>Each workspace is reachable through a private endpoint</td><td>✅ workspace to private endpoint join</td><td>MLG-SE-R</td></tr><tr><td>WAF-ML-SE-05</td><td>Managed outbound access is set to Allow only approved outbound</td><td>✅ managedNetwork.isolationMode is AllowOnlyApprovedOutbound</td><td>MLG-SE-C, MLG-SE-R</td></tr><tr><td>WAF-ML-SE-06</td><td>Dependent services (Storage, Key Vault, Container Registry) use private endpoints with public access disabled</td><td>❌ Manual — the workspace-to-dependency link is not collected; storage accounts with no default-deny firewall attached</td><td>MLG-SE-R</td></tr><tr><td>WAF-ML-SE-07</td><td>Workspaces authenticate to other services with managed identities</td><td>✅ workspace identity type</td><td>MLG-SE-R</td></tr><tr><td>WAF-ML-SE-08</td><td>Local authentication is disabled on compute clusters and instances</td><td>❌ Manual — compute resources are child resources, not collected</td><td>MLG-SE-R</td></tr><tr><td>WAF-ML-SE-09</td><td>The public SSH port is closed on compute clusters (remoteLoginPortPublicAccess = Disabled)</td><td>❌ Manual — compute resources are child resources, not collected</td><td>MLG-SE-R</td></tr><tr><td>WAF-ML-SE-10</td><td>Compute gets no public IP address (enableNodePublicIp = false)</td><td>❌ Manual — compute resources are child resources, not collected</td><td>MLG-SE-R</td></tr><tr><td>WAF-ML-SE-11</td><td>Compute instances are recreated to pick up the latest operating system image</td><td>❌ Manual — image age is not collected</td><td>MLG-SE-R</td></tr><tr><td>WAF-ML-SE-12</td><td>Workspace access uses Microsoft Entra groups and least-privilege RBAC, per use case</td><td>❌ Manual — role assignments attached; scope-to-workspace review is judgement</td><td>MLG-SE-C, MLG-SE-R</td></tr><tr><td>WAF-ML-SE-13</td><td>Model catalog deployments, container registries and Python packages are restricted to approved sources</td><td>❌ Manual — registry and package policy is workspace configuration, not collected</td><td>MLG-SE-C, MLG-SE-R</td></tr><tr><td>WAF-ML-SE-14</td><td>Data at rest uses customer-managed keys where required</td><td>❌ Manual — customer-managed keys are requirement-driven; the workspaces whose encryption status is not Enabled are attached as evidence (Foundry project workspaces inherit their hub&#39;s and are skipped)</td><td>MLG-SE-C, MLG-SE-R</td></tr><tr><td>WAF-ML-SE-15</td><td>Data exfiltration prevention limits egress to approved storage accounts</td><td>❌ Manual — network policy, not collected</td><td>MLG-SE-R</td></tr></tbody></table><h3 id="cost-optimization-waf-ml-co-—-7-items" tabindex="-1">Cost optimization (WAF-ML-CO) — 7 items <a class="header-anchor" href="#cost-optimization-waf-ml-co-—-7-items" aria-label="Permalink to &quot;Cost optimization (WAF-ML-CO) — 7 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ML-CO-01</td><td>Compute SKU family (CPU, GPU, memory-optimised) is matched to the workload and the choice is documented</td><td>❌ Manual — architecture judgement</td><td>MLG-CO-C, MLG-CO-R</td></tr><tr><td>WAF-ML-CO-02</td><td>Compute clusters autoscale to a minimum of zero nodes with a deliberate idle time</td><td>❌ Manual — compute clusters are child resources, not collected</td><td>MLG-CO-R</td></tr><tr><td>WAF-ML-CO-03</td><td>Compute instances shut down when idle or on a schedule</td><td>❌ Manual — compute instances are child resources, not collected</td><td>MLG-CO-C, MLG-CO-R</td></tr><tr><td>WAF-ML-CO-04</td><td>Training runs have termination policies</td><td>❌ Manual — job definition, not ARM</td><td>MLG-CO-R</td></tr><tr><td>WAF-ML-CO-05</td><td>Low-priority VMs are used for batch work that tolerates interruption, and training is tested for parallelisation</td><td>❌ Manual — architecture judgement</td><td>MLG-CO-C, MLG-CO-R</td></tr><tr><td>WAF-ML-CO-06</td><td>Reserved VM Instances cover steady, predictable usage</td><td>❌ Manual — reservations attached</td><td>MLG-CO-C, MLG-CO-R</td></tr><tr><td>WAF-ML-CO-07</td><td>Policies and quotas bound compute, and CPU and GPU utilisation is monitored</td><td>❌ Manual — quota and utilisation are not collected</td><td>MLG-CO-C</td></tr></tbody></table><h3 id="operational-excellence-waf-ml-oe-—-8-items" tabindex="-1">Operational excellence (WAF-ML-OE) — 8 items <a class="header-anchor" href="#operational-excellence-waf-ml-oe-—-8-items" aria-label="Permalink to &quot;Operational excellence (WAF-ML-OE) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ML-OE-01</td><td>The number of workspaces is kept to what separation requirements need</td><td>❌ Manual — workspaces attached for counting</td><td>MLG-OE-R</td></tr><tr><td>WAF-ML-OE-02</td><td>Model catalogs and registries store, version and share machine learning assets</td><td>❌ Manual — registry contents are not collected</td><td>MLG-OE-C, MLG-OE-R</td></tr><tr><td>WAF-ML-OE-03</td><td>MLOps pipelines automate data preparation, training and scoring</td><td>❌ Manual — pipeline practice, not ARM</td><td>MLG-OE-C</td></tr><tr><td>WAF-ML-OE-04</td><td>Workspaces, compute and environments are deployed with infrastructure as code</td><td>❌ Manual — deployment method is not an ARM property</td><td>MLG-OE-C</td></tr><tr><td>WAF-ML-OE-05</td><td>Deployed model performance and data drift are monitored</td><td>❌ Manual — model-monitor configuration is not collected</td><td>MLG-OE-C, MLG-OE-R</td></tr><tr><td>WAF-ML-OE-06</td><td>Online endpoints send telemetry to Application Insights</td><td>❌ Manual — Application Insights components attached (link to endpoints is not collected)</td><td>MLG-OE-C, MLG-OE-R</td></tr><tr><td>WAF-ML-OE-07</td><td>Resource logs are collected for Machine Learning workspaces</td><td>❌ Manual — type not yet in the diagnostic-settings sweep (proposed in the report)</td><td>MLG-OE-R</td></tr><tr><td>WAF-ML-OE-08</td><td>Curated environments are used where available</td><td>❌ Manual — environment choice, not collected</td><td>MLG-OE-C, MLG-OE-R</td></tr></tbody></table><h3 id="performance-efficiency-waf-ml-pe-—-5-items" tabindex="-1">Performance efficiency (WAF-ML-PE) — 5 items <a class="header-anchor" href="#performance-efficiency-waf-ml-pe-—-5-items" aria-label="Permalink to &quot;Performance efficiency (WAF-ML-PE) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-ML-PE-01</td><td>Acceptable training time and retrain frequency are defined</td><td>❌ Manual — target-setting, not ARM</td><td>MLG-PE-C</td></tr><tr><td>WAF-ML-PE-02</td><td>Performance targets (response time, requests per second, error rate, uptime) are defined for deployed models</td><td>❌ Manual — target-setting, not ARM</td><td>MLG-PE-C</td></tr><tr><td>WAF-ML-PE-03</td><td>Compute clusters, not instances, are used where autoscaling is needed for training</td><td>❌ Manual — compute resources are child resources, not collected</td><td>MLG-PE-C, MLG-PE-R</td></tr><tr><td>WAF-ML-PE-04</td><td>Deployment environments autoscale to demand</td><td>❌ Manual — autoscale settings attached (link to endpoints is not collected)</td><td>MLG-PE-C, MLG-PE-R</td></tr><tr><td>WAF-ML-PE-05</td><td>Deployed model and endpoint infrastructure are monitored against baselines</td><td>❌ Manual — monitoring configuration, not collected</td><td>MLG-PE-C, MLG-PE-R</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pillar</th><th>Items</th><th>Automated (✅)</th><th>Manual (❌)</th></tr></thead><tbody><tr><td>Reliability</td><td>9</td><td>0</td><td>9</td></tr><tr><td>Security</td><td>15</td><td>5</td><td>10</td></tr><tr><td>Cost optimization</td><td>7</td><td>0</td><td>7</td></tr><tr><td>Operational excellence</td><td>8</td><td>0</td><td>8</td></tr><tr><td>Performance efficiency</td><td>5</td><td>0</td><td>5</td></tr><tr><td><strong>Total</strong></td><td><strong>44</strong></td><td><strong>5</strong></td><td><strong>39</strong></td></tr></tbody></table><p>Every automated item is gated on its resources (or its diagnostic-coverage rows) existing, so an estate without them reports the item Not assessed. The rules live in <code>src/assess/rules/waf.machinelearning.yaml</code>.</p>',24)])])}const p=e(o,[["render",n]]);export{m as __pageData,p as default};
